    for (int i = 0; i < MAX_BIT; ++i) {
      if ((ans >> i & 1) == 0) {
        // Set x's 0 with k's bit if the running bit of k is 1.
        if ((k >> BINARY_INDEX & 1) == 1)
          ans |= 1L << i;
        ++BINARY_INDEX;
