 public:
  int medianOfUniquenessArray(vector<int>& nums) {
    const int n = nums.size();
    const long subarryCount = n * (n + 1L) / 2;
    const long medianCount = (subarryCount + 1) / 2;
    int l = 1;
    int r = n;

    while (l < r) {
      const int m = (l + r) / 2;
      if (subarrayWithAtMostKDistinct(nums, m) >= medianCount)
        r = m;
      else
        l = m + 1;
    }

    return l;
  }

