    int prevTime = 0;

    for (const auto& [time, indices] : timeToIndices) {
      area += (time - prevTime) * diffPerSecond;
      ans = max(ans, area);
      prevTime = time;
      for (const int i : indices)
        if (directions[i] == 'U') {
          directions[i] = 'D';
          diffPerSecond -= 2;
        } else {
          directions[i] = 'U';
          diffPerSecond += 2;
        }
    }

    return ans;
  }
