    int[][][] dp = new int[n + 1][1 << (n + 1)][2];

    for (int i = 0; i < n + 1; ++i)
      for (int mask = 0; mask < MAX_MASK - 1; ++mask)
        dp[i][mask] = new int[] {-MAX, MAX};

    for (int mask = MAX_MASK - 2; mask >= 0; --mask)
      for (int i = 0; i < n + 1; ++i)
        for (int turn = 0; turn < 2; ++turn)
          for (int j = 0; j < n; ++j) {
            if ((mask >> j & 1) == 1)
              continue;
